import{_ as o,c as r,aM as a,e as i,p as n,au as s,o as l,a3 as c}from"./chunks/framework.DhAtJbM3.js";const v=JSON.parse('{"title":"Accessibility","description":"Reka UI follow the WAI-ARIA authoring practices guidelines and are tested in a wide selection of modern browsers and commonly used assistive technologies.","frontmatter":{"title":"Accessibility","description":"Reka UI follow the WAI-ARIA authoring practices guidelines and are tested in a wide selection of modern browsers and commonly used assistive technologies.","sidebar":true},"headers":[{"level":2,"title":"WAI-ARIA","slug":"wai-aria","link":"#wai-aria","children":[]},{"level":2,"title":"Accessible Labels","slug":"accessible-labels","link":"#accessible-labels","children":[]},{"level":2,"title":"Keyboard Navigation","slug":"keyboard-navigation","link":"#keyboard-navigation","children":[]},{"level":2,"title":"Focus Management","slug":"focus-management","link":"#focus-management","children":[]}],"relativePath":"docs/overview/accessibility.md","filePath":"docs/overview/accessibility.md","lastUpdated":1741141824000}'),d={name:"docs/overview/accessibility.md"};function p(h,e,m,u,g,b){const t=s("Description");return l(),r("div",null,[e[1]||(e[1]=a('<h1 id="accessibility" tabindex="-1" class="group relative border-none mb-4 lg:-ml-2 lg:pl-2 lg:pr-2 w-max">Accessibility <a class="header-anchor [&amp;_span]:focus:opacity-100 [&amp;_span_&gt;_span]:focus:outline" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;"><span class="absolute top-0 -ml-8 hidden items-center border-0 opacity-0 group-hover:opacity-100 focus:opacity-100 lg:flex">​<span class="flex h-6 w-6 items-center justify-center rounded-md outline-2 outline-primary text-green-400 shadow-sm hover:text-green-700 hover:shadow dark:bg-primary/20 dark:text-primary/80 dark:shadow-none dark:hover:bg-primary/40 dark:hover:text-primary"><svg width="12" height="12" fill="none" aria-hidden="true"><path d="M3.75 1v10M8.25 1v10M1 3.75h10M1 8.25h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path></svg></span></span></a></h1>',1)),i(t,null,{default:n(()=>e[0]||(e[0]=[c(" Reka UI follow the WAI-ARIA authoring practices guidelines and are tested in a wide selection of modern browsers and commonly used assistive technologies. ")])),_:1}),e[2]||(e[2]=a('<p>We take care of many of the difficult implementation details related to accessibility, including <code>aria</code> and <code>role</code> attributes, focus management, and keyboard navigation. That means that users should be able to use our components as-is in most contexts and rely on functionality to follow the expected accessibility design patterns.</p><h2 id="wai-aria" tabindex="-1" class="group relative border-none mb-4 lg:-ml-2 lg:pl-2 lg:pr-2 w-max">WAI-ARIA <a class="header-anchor [&amp;_span]:focus:opacity-100 [&amp;_span_&gt;_span]:focus:outline" href="#wai-aria" aria-label="Permalink to &quot;WAI-ARIA&quot;"><span class="absolute top-0 -ml-8 hidden items-center border-0 opacity-0 group-hover:opacity-100 focus:opacity-100 lg:flex">​<span class="flex h-6 w-6 items-center justify-center rounded-md outline-2 outline-primary text-green-400 shadow-sm hover:text-green-700 hover:shadow dark:bg-primary/20 dark:text-primary/80 dark:shadow-none dark:hover:bg-primary/40 dark:hover:text-primary"><svg width="12" height="12" fill="none" aria-hidden="true"><path d="M3.75 1v10M8.25 1v10M1 3.75h10M1 8.25h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path></svg></span></span></a></h2><p><a href="https://www.w3.org/TR/wai-aria-1.2/" target="_blank" rel="noreferrer">WAI-ARIA</a>, published and maintained by the W3C, specifies the semantics for many common UI patterns that show up in Reka UI. This is designed to provide meaning for controls that aren&#39;t built using elements provided by the browser. For example, if you use a <code>div</code> instead of a <code>button</code> element to create a button, there are attributes you need to add to the <code>div</code> in order to convey that it&#39;s a button for screen readers or voice recognition tools.</p><p>In addition to semantics, there are behaviors that are expected from different types of components. A <code>button</code> element is going to respond to certain interactions in ways that a <code>div</code> will not, so it&#39;s up to the developer to reimplement those interactions with JavaScript. The <a href="https://www.w3.org/TR/wai-aria-practices-1.2/" target="_blank" rel="noreferrer">WAI-ARIA authoring practices</a> provide additional guidance for implementing behaviors for various controls that come with Reka UI.</p><h2 id="accessible-labels" tabindex="-1" class="group relative border-none mb-4 lg:-ml-2 lg:pl-2 lg:pr-2 w-max">Accessible Labels <a class="header-anchor [&amp;_span]:focus:opacity-100 [&amp;_span_&gt;_span]:focus:outline" href="#accessible-labels" aria-label="Permalink to &quot;Accessible Labels&quot;"><span class="absolute top-0 -ml-8 hidden items-center border-0 opacity-0 group-hover:opacity-100 focus:opacity-100 lg:flex">​<span class="flex h-6 w-6 items-center justify-center rounded-md outline-2 outline-primary text-green-400 shadow-sm hover:text-green-700 hover:shadow dark:bg-primary/20 dark:text-primary/80 dark:shadow-none dark:hover:bg-primary/40 dark:hover:text-primary"><svg width="12" height="12" fill="none" aria-hidden="true"><path d="M3.75 1v10M8.25 1v10M1 3.75h10M1 8.25h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path></svg></span></span></a></h2><p>With many built-in form controls, the native HTML <code>label</code> element is designed to provide semantic meaning and context for corresponding <code>input</code> elements. For non-form control elements, or for custom controls like those provided by Reka UI, <a href="https://www.w3.org/TR/wai-aria-1.2/#namecalculation" target="_blank" rel="noreferrer">WAI-ARIA provides a specification</a> for how to provide accessible names and descriptions to those controls.</p><p>Where possible, Reka UI include abstractions to make labelling our controls simple. The <a href="./../components/label"><code>Label</code></a> primitive is designed to work with many of our controls. Ultimately it&#39;s up to you to provide those labels so that users have the proper context when navigating your application.</p><h2 id="keyboard-navigation" tabindex="-1" class="group relative border-none mb-4 lg:-ml-2 lg:pl-2 lg:pr-2 w-max">Keyboard Navigation <a class="header-anchor [&amp;_span]:focus:opacity-100 [&amp;_span_&gt;_span]:focus:outline" href="#keyboard-navigation" aria-label="Permalink to &quot;Keyboard Navigation&quot;"><span class="absolute top-0 -ml-8 hidden items-center border-0 opacity-0 group-hover:opacity-100 focus:opacity-100 lg:flex">​<span class="flex h-6 w-6 items-center justify-center rounded-md outline-2 outline-primary text-green-400 shadow-sm hover:text-green-700 hover:shadow dark:bg-primary/20 dark:text-primary/80 dark:shadow-none dark:hover:bg-primary/40 dark:hover:text-primary"><svg width="12" height="12" fill="none" aria-hidden="true"><path d="M3.75 1v10M8.25 1v10M1 3.75h10M1 8.25h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path></svg></span></span></a></h2><p>Many complex components, like <a href="./../components/tabs"><code>Tabs</code></a> and <a href="./../components/dialog"><code>Dialog</code></a>, come with expectations from users on how to interact with their content using a keyboard or other non-mouse input modalities. Reka UI provide basic keyboard support in accordance with the <a href="https://www.w3.org/TR/wai-aria-practices-1.2/" target="_blank" rel="noreferrer">WAI-ARIA authoring practices</a>.</p><h2 id="focus-management" tabindex="-1" class="group relative border-none mb-4 lg:-ml-2 lg:pl-2 lg:pr-2 w-max">Focus Management <a class="header-anchor [&amp;_span]:focus:opacity-100 [&amp;_span_&gt;_span]:focus:outline" href="#focus-management" aria-label="Permalink to &quot;Focus Management&quot;"><span class="absolute top-0 -ml-8 hidden items-center border-0 opacity-0 group-hover:opacity-100 focus:opacity-100 lg:flex">​<span class="flex h-6 w-6 items-center justify-center rounded-md outline-2 outline-primary text-green-400 shadow-sm hover:text-green-700 hover:shadow dark:bg-primary/20 dark:text-primary/80 dark:shadow-none dark:hover:bg-primary/40 dark:hover:text-primary"><svg width="12" height="12" fill="none" aria-hidden="true"><path d="M3.75 1v10M8.25 1v10M1 3.75h10M1 8.25h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path></svg></span></span></a></h2><p>Proper keyboard navigation and good labelling often go hand-in-hand with managing focus. When a user interacts with an element and something changes as a result, it&#39;s often helpful to move focus with the interaction so that the next tab stop is logical depending on the new context of the app. And for screen reader users, moving focus often results in an announcement to convey this new context, which relies on proper labelling.</p><p>In many Reka UI, we move focus based on the interactions a user normally takes in a given component. For example, in <a href="./../components/alert-dialog"><code>AlertDialog</code></a>, when the modal is opened, focus is programmatically moved to a <code>Cancel</code> button element to anticipate a response to the prompt.</p>',12))])}const y=o(d,[["render",p]]);export{v as __pageData,y as default};
